def transform(grid):
    """Read the rectangle hidden by 8 via the grid's central row reflection."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
    c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
    # The 30x30 pattern reflects across the horizontal axis between rows 15/16.
    # If the reflected partner is also covered, use the matching horizontal
    # reflection on the same row to expose the hidden values.
    axis_sum = h + 1
    result = []
    for r in range(r0, r1 + 1):
        partner = axis_sum - r
        row = []
        for c in range(c0, c1 + 1):
            if 0 <= partner < h and grid[partner][c] != 8:
                row.append(grid[partner][c])
            else:
                row.append(grid[r][w - 1 - c])
        result.append(row)
    return result

