def transform(grid):
    """Extract the zero-marked patch, restoring it from horizontal reflection."""
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zeros:
        return []
    r0 = min(r for r, _ in zeros)
    r1 = max(r for r, _ in zeros)
    c0 = min(c for _, c in zeros)
    c1 = max(c for _, c in zeros)
    # A marked patch meeting the outer edge excludes that edge's border row/column.
    if r0 == 0:
        r0 += 1
    if r1 == h - 1:
        r1 -= 1
    if c0 == 0:
        c0 += 1
    if c1 == w - 1:
        c1 -= 1
    return [[grid[h - 1 - r][c] if grid[r][c] == 0 else grid[r][c]
             for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]

