def transform(grid):
    h, w = len(grid), len(grid[0])
    # The most frequent color is the blank canvas; each detached horizontal bar
    # is one item in the compact color inventory.
    freq = {}
    for row in grid:
        for color in row:
            freq[color] = freq.get(color, 0) + 1
    background = max(freq, key=freq.get)

    seen = set()
    component_counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
