def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, out = set(), {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1 or (r, c) in seen:
                continue
            cells = {(r, c)}
            todo = [(r, c)]
            seen.add((r, c))
            while todo:
                x, y = todo.pop()
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1),
                               (x-1,y-1),(x-1,y+1),(x+1,y-1),(x+1,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny)); cells.add((nx, ny)); todo.append((nx, ny))
            out.setdefault(color, []).append(cells)
    return out


def _nearby_groups(points, radius):
    remaining = set(points)
    groups = []
    while remaining:
        group = {remaining.pop()}
        changed = True
        while changed:
            changed = False
            for p in list(remaining):
                if any(max(abs(p[0]-q[0]), abs(p[1]-q[1])) <= radius for q in group):
                    remaining.remove(p); group.add(p); changed = True
        groups.append(group)
    return groups


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comps = _components(grid)
    if 4 not in comps:
        return out
    stencil = max(comps[4], key=len)
    top = min(r for r, c in stencil)
    left = min(c for r, c in stencil)
    shape = {(r-top, c-left) for r, c in stencil}
    height = max(r for r, c in shape) + 1
    width = max(c for r, c in shape) + 1
    radius = max(height, width) - 1
    for color, objects in comps.items():
        if color == 4:
            continue
        points = set().union(*objects)
        for seed in _nearby_groups(points, radius):
            placements = set()
            for sr, sc in seed:
                for vr, vc in shape:
                    dr, dc = sr-vr, sc-vc
                    placed = frozenset((r+dr, c+dc) for r, c in shape)
                    if seed <= placed and all(0 <= r < h and 0 <= c < w for r, c in placed):
                        placements.add(placed)
            if placements:
                # With multiple valid alignments (e.g. an adjacent-color collision),
                # use the translated shape nearest the seed cluster's centroid.
                def rank(place):
                    cr = sum(r for r, c in place) / len(place)
                    cc = sum(c for r, c in place) / len(place)
                    sr = sum(r for r, c in seed) / len(seed)
                    sc = sum(c for r, c in seed) / len(seed)
                    return (abs(cr - sr) + abs(cc - sc), tuple(sorted(place)))
                for r, c in min(placements, key=rank):
                    out[r][c] = color
    return out

