import sqlite3,re
p='/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-hermesagentlearner-1790687644/attempts/733b986490a94152ab93b0528437cda1/system/state/hermes/state.db'; c=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
sid='3667b612-5a4e-46cc-b041-cbcf10244369'
for mid,txt in c.execute("select id,content from messages where session_id=? and role='user' and content like '%Demo pair % input%' order by id",(sid,)):
 if not txt: continue
 for match in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|\Z)',txt,re.S):
  n,h,w,ins,oh,ow,outs=match.groups(); g=[list(map(int,r.split())) for r in ins.strip().splitlines()]; o=[list(map(int,r.split())) for r in outs.strip().splitlines()]
  print('PAIR',n,'mask',len(o),len(o[0]),'output',o)
  # find output exact in original at any location; orientations
  for name,pat in [('exact',o),('hflip',[r[::-1] for r in o]),('vflip',o[::-1]),('rot180',[r[::-1] for r in o[::-1]])]:
   spots=[]
   for y in range(len(g)-len(pat)+1):
    for x in range(len(g[0])-len(pat[0])+1):
     if [r[x:x+len(pat[0])] for r in g[y:y+len(pat)]]==pat: spots.append((y,x))
   if spots: print(' ',name,spots)
  # print masked rectangle positions of 8
  pos=[(y,x) for y,row in enumerate(g) for x,v in enumerate(row) if v==8]
  print('  8bbox',min(y for y,x in pos),max(y for y,x in pos),min(x for y,x in pos),max(x for y,x in pos))
